mapper.select:
SELECT l.`id` AS id, l.`crzdbh` AS crzdbh, l.`dkmc` AS dkmc, l.`xzqh` AS xzqh, l.`xmfl` AS xmfl, (SELECT COUNT(1) FROM `xj_kjkfb_supporting_facilities` f WHERE f.`crzdbh` = l.`crzdbh`) AS facilityCount FROM `t_land` l WHERE l.`del_flag` = 0
AND l.`xzqh` = #{xzqh}
AND (l.`crzdbh` LIKE CONCAT('%', #{keyword}, '%') OR l.`dkmc` LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY l.`crzdbh` LIMIT #{limit}
